from functools import cached_property

class OrderDraft:
    def __init__(self, rows): self.rows = rows

    @cached_property
    def publish_errors(self):                 # runs once, on first use
        return [r for r in self.rows if (r.get("qty") or 0) <= 0]

    def assert_publishable(self):
        if self.publish_errors: raise ValueError(self.publish_errors)

